input.command:
# Find and stop the dotnet process
$dotnetProcess = Get-Process dotnet -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowTitle -like "*Umbraco*" -or $_.CommandLine -like "*Umbraco.Bench.Umbraco*"} | Select-Object -First 1
if ($dotnetProcess) {
    Write-Host "Stopping Umbraco (PID: $($dotnetProcess.Id))"
    Stop-Process -Id $dotnetProcess.Id -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
    Write-Host "Umbraco stopped"
} else {
    # Kill all dotnet processes
