@model Umbraco.Bench.Umbraco.Models.Blocks.PostListBlockModel

<section class="my-12">
    @if (!string.IsNullOrEmpty(Model?.Title))
    {
        <h2 class="text-3xl font-bold mb-8">@Model.Title</h2>
    }
    <div class="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
        @{
            var blogHome = this.Page.AncestorOrSelf<BlogFrontPage>();
            if (blogHome != null)
            {
                var posts = blogHome.Children<BlogPost>();
                foreach (var post in posts)
                {
                    <article class="border rounded-lg p-6 hover:shadow-lg transition">
                        <h3 class="text-xl font-semibold mb-2">
                            <a href="@post.Url()" class="text-blue-600 hover:underline">@post.Name</a>
                        </h3>
                        @if (post.Value("publishDate") is DateTime pubDate)
                        {
                            <p class="text-sm text-gray-500 mb-4">@pubDate.ToString("MMMM d, yyyy")</p>
                        }
                        <p class="text-gray-700">@post.Value("title")</p>
                    </article>
                }
            }
        }
    </div>
</section>

